using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPlayerPurifyUseBattleActionOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnPlayerPurifyUseBattleActionOmenData")]
public class OnPlayerPurifyUseBattleActionOmenData : OmenData
{
	private const string everyPurifyChantTextID = "EveryPurifyChant";

	private const string everyPurifyOnEnemyChantTextID = "EveryPurifyEnemyChant";

	private const string everyPurifyOnSentinelChantTextID = "EveryPurifySentinelChant";

	[Header("On Player Purify Use Battle Action")]
	[SerializeField]
	private PlayerPurifyOmenType playerPurifyOmenType;

	[SerializeField]
	private bool resetBetweenBattles;

	private Action omenAction;

	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			if (OmenTriggered())
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				omenInstance.StopBlinkingFeedback();
			}
			else if (OmenAboutToTrigger())
			{
				omenInstance.PlayBlinkingFeedback();
			}
			ActivateOmen();
			omenInstance.UpdateOmenCounter();
		};
		if (playerPurifyOmenType == PlayerPurifyOmenType.ENEMY)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnEnemyOmenActions.Add(omenAction);
		}
		else if (playerPurifyOmenType == PlayerPurifyOmenType.SENTINEL)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnSentinelsOmenActions.Add(omenAction);
		}
		else if (playerPurifyOmenType == PlayerPurifyOmenType.ANYTARGET)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOmenActions.Add(omenAction);
		}
		if (resetBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
			this.omenInstance = omenInstance;
		}
	}

	private bool OmenTriggered()
	{
		return counter == TriggerAmount - 1;
	}

	private bool OmenAboutToTrigger()
	{
		return counter == TriggerAmount - 2;
	}

	public override void OmenRemoved()
	{
		if (playerPurifyOmenType == PlayerPurifyOmenType.ENEMY)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnEnemyOmenActions.Remove(omenAction);
		}
		else if (playerPurifyOmenType == PlayerPurifyOmenType.SENTINEL)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOnSentinelsOmenActions.Remove(omenAction);
		}
		else if (playerPurifyOmenType == PlayerPurifyOmenType.ANYTARGET)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyOmenActions.Remove(omenAction);
		}
		if (resetBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
			omenInstance = null;
		}
	}

	public override string OmenConvertedDescription()
	{
		string iD = "";
		if (playerPurifyOmenType == PlayerPurifyOmenType.ENEMY)
		{
			iD = "EveryPurifyEnemyChant";
		}
		else if (playerPurifyOmenType == PlayerPurifyOmenType.SENTINEL)
		{
			iD = "EveryPurifySentinelChant";
		}
		else if (playerPurifyOmenType == PlayerPurifyOmenType.ANYTARGET)
		{
			iD = "EveryPurifyChant";
		}
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(iD);
		return string.Concat(str2: BattleAction.GetActionDescription(ActionValue).LowercaseFirst(), str0: Smart.Format(localizedString, TriggerAmount), str1: ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace());
	}
}
